import subprocess
packages=['inir-protocol','inir-companiond','inir-inputd','inir-mega','inir-mpdd','inir-native','inir-theme']
mask=0
for i,pkg in enumerate(packages):
    r=subprocess.run(['cargo','fmt','--package',pkg,'--','--check'],cwd='native',stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    if r.returncode != 0: mask |= (1 << i)
allrc=subprocess.run(['cargo','fmt','--all','--','--check'],cwd='native',stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL).returncode
if allrc == 0 and mask == 0: raise SystemExit(0)
if allrc == 0 and mask != 0: raise SystemExit(240)
if allrc != 0 and mask == 0: raise SystemExit(241)
raise SystemExit(mask)
